def create_project(base_dir='.'):
    base_dir = Path(base_dir).resolve()
    project_root = base_dir #/ PROJECT_NAME
    project_root.mkdir(parents=True, exist_ok=True)
    for directory in DIRECTORIES:
        (project_root / directory).mkdir(parents=True, exist_ok=True)
    created = 0
    skipped = 0
    for relative_path, content in FILES.items():
        file_path = project_root / relative_path
        file_path.parent.mkdir(parents=True, exist_ok=True)
        if file_path.exists():
            skipped += 1
            continue
        file_path.write_text(content, encoding='utf-8')
        created += 1
    print('=' * 76)
    print('OnlyNativeIQ project skeleton created successfully')
    print('=' * 76)
    print(f'Location : {project_root}')
    print(f'Created  : {created} files')
    print(f'Skipped  : {skipped} existing files')
    print()
    print('NEXT STEPS')
    print('1. cd OnlyNativeIQ')
    print('2. python -m venv .venv')
    print(r'3. Windows: .venv\Scripts\activate')
    print('4. python -m pip install --upgrade pip')
    print('5. pip install -r requirements.txt')
    print('6. Copy Corpus v2.0 files into matching knowledge_base subfolders')
    print('7. Copy .env.example to .env and add the selected API key')
    print('8. Start implementation with src/ingestion/document_loader.py')
    return project_root

if __name__ == '__main__':
    create_project()